#!/usr/bin/env node
// MIT — Local authoring commands for the existing private collection store.
import { realpath } from 'node:fs/promises';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { openCollections } from '../collections/model.mjs';
import { initializationBytes } from '../initialization.mjs';
import { openCollectionComposer, inspectCollectionCatalog } from './model.mjs';
import { fields, need } from './plan.mjs';

export const HELP = [
  'Starforge customer request plans',
  '',
  '  starforge buyer-collection-plans list --directory ABS',
  '  starforge buyer-collection-plans show --directory ABS --id PLAN --revision SHA256',
  '  starforge buyer-collection-plans save --directory ABS --file ABS_PLAN_JSON',
  '  starforge buyer-collection-plans catalog --file ABS_CATALOG_JSON',
  '  starforge buyer-collection-plans editions --directory ABS',
  '  starforge buyer-collection-plans edition --directory ABS --collection ID',
  '  starforge buyer-collection-plans prepare --directory ABS --id PLAN --revision SHA256',
  '    --collection ID --name NAME [--value name=value ...]',
  '  starforge buyer-collection-plans create --directory ABS --collection ID',
  '    --edition-sha256 SHA256 --preview-sha256 SHA256',
  '',
  'Use an existing Request Collections directory. All output is JSON.',
  'Save keeps immutable plan revisions. Prepare retains one named period and its source inputs.',
  'Repeat the same prepare request to resume its original identity.',
  'Create joins that reviewed period to the original collection screen and CLI.',
  'Queue, approval, execution and recovery remain in the original buyer-collections command.',
].join('\n');
const MODES = {
  list: ['--directory'], show: ['--directory', '--id', '--revision'],
  save: ['--directory', '--file'], catalog: ['--file'],
  editions: ['--directory'], edition: ['--directory', '--collection'],
  prepare: ['--directory', '--id', '--revision', '--collection', '--name'],
  create: ['--directory', '--collection', '--edition-sha256', '--preview-sha256'],
};
export function readCollectionComposerArguments(args) {
  need(Array.isArray(args) && args.every(item => typeof item === 'string'), 'COLLECTION_AUTHORING_CLI_ARGUMENT');
  if (args.length === 0 || args.length === 1 && ['help', '--help', '-h'].includes(args[0]))
    return { mode: 'help', options: {}, values: {} };
  const [mode, ...rest] = args;
  need(Object.hasOwn(MODES, mode) && rest.length % 2 === 0, 'COLLECTION_AUTHORING_CLI_ARGUMENT');
  const options = {}, values = {};
  for (let index = 0; index < rest.length; index += 2) {
    const key = rest[index], value = rest[index + 1];
    need(value.length > 0, 'COLLECTION_AUTHORING_CLI_VALUE_REQUIRED');
    if (key === '--value') {
      const equals = value.indexOf('='), name = value.slice(0, equals);
      need(mode === 'prepare' && equals >= 1 && /^[A-Za-z][A-Za-z0-9_]{0,63}$/.test(name)
        && !Object.hasOwn(values, name), 'COLLECTION_AUTHORING_CLI_PARAMETER_INVALID');
      values[name] = value.slice(equals + 1);
    } else {
      need(MODES[mode].includes(key) && !Object.hasOwn(options, key), 'COLLECTION_AUTHORING_CLI_ARGUMENT');
      options[key] = value;
    }
  }
  need(MODES[mode].every(key => Object.hasOwn(options, key)), 'COLLECTION_AUTHORING_CLI_VALUE_REQUIRED');
  return { mode, options, values };
}
export async function runCollectionComposerCommand(args) {
  const { mode, options, values } = readCollectionComposerArguments(args);
  if (mode === 'help') return { help: HELP };
  if (mode === 'catalog') return inspectCollectionCatalog({ path: options['--file'] });
  const collections = await openCollections({ directory: options['--directory'], existingOnly: true });
  const composer = openCollectionComposer({ collections });
  try {
    if (mode === 'list') return await composer.listPlans();
    if (mode === 'show') return await composer.inspectPlan(options['--id'], options['--revision']);
    if (mode === 'save') {
      let input;
      try { input = JSON.parse(new TextDecoder('utf-8', { fatal: true })
        .decode(await initializationBytes(options['--file'], 1048576))); }
      catch (error) {
        if (error.code) throw error;
        need(false, 'COLLECTION_AUTHORING_JSON_INVALID');
      }
      // Accept the portable plain plan or the complete saved-plan response.
      const plan = input?.schema === 'stellar-forge.sf88.collection-plan-revision.v1'
        ? fields(input, ['schema', 'id', 'planSha256', 'savedAt', 'plan']).plan : input;
      return await composer.savePlan({ plan });
    }
    if (mode === 'editions') return await composer.listEditions();
    if (mode === 'edition') return await composer.inspectEdition(options['--collection']);
    if (mode === 'prepare') return await composer.prepareEdition({
      planId: options['--id'], planSha256: options['--revision'],
      collectionId: options['--collection'], name: options['--name'], values,
    });
    return await composer.createEdition({ collectionId: options['--collection'],
      expectedEditionSha256: options['--edition-sha256'], expectedPreviewSha256: options['--preview-sha256'] });
  } finally { composer.close(); await collections.close(); }
}
export async function main(args = process.argv.slice(2)) {
  const value = await runCollectionComposerCommand(args);
  process.stdout.write((value.help ?? JSON.stringify(value, null, 2)) + '\n');
  return value;
}
if (process.argv[1] && await realpath(resolve(process.argv[1])).then(
  entry => pathToFileURL(entry).href === import.meta.url, () => false))
  main().catch(error => { console.error(error.code ?? 'COLLECTION_AUTHORING_FAILED'); process.exitCode = 1; });

export interface PlanParameter {
  name: string;
  label?: string;
  default?: string;
}
export type OperatorBinding =
  | { operatorWorkspace: string; operatorConfigFile?: never }
  | { operatorConfigFile: string; operatorWorkspace?: never };
export type PlannedRequest = OperatorBinding & {
  key: string;
  name: string;
  discoveryFile: string;
  rowIndex: number;
  acceptIndex: number;
  url: string;
  method: "GET" | "HEAD" | "POST" | "PUT" | "PATCH" | "DELETE";
  bodyFile?: string;
  headers?: Record<string, string>;
  ticketFile?: string;
  ticketHeader?: string;
  responseOut?: string;
};
export interface CollectionPlan {
  schema: "stellar-forge.sf88.collection-plan.v1";
  id: string;
  name: string;
  description?: string;
  parameters?: PlanParameter[];
  requests: PlannedRequest[];
}
export interface SavedPlan {
  schema: "stellar-forge.sf88.collection-plan-revision.v1";
  id: string;
  planSha256: string;
  savedAt: string;
  plan: CollectionPlan & { parameters: PlanParameter[] };
}
export interface PlanSummary {
  id: string;
  planSha256: string;
  name: string;
  description?: string;
  savedAt?: string;
  requestCount?: number;
  parameters?: PlanParameter[];
  error?: string;
}
export interface AcceptedCatalogTerms {
  index: number;
  scheme?: string;
  network?: string;
  asset?: string;
  payTo?: string;
  amount?: string;
  maxTimeoutSeconds?: number;
  extra?: Record<string, unknown> & { paymentFlow?: string };
  [key: string]: unknown;
}
export interface CatalogRow {
  index: number;
  resource: string;
  description: string;
  method: string;
  accepts: AcceptedCatalogTerms[];
  listing: unknown;
}
export interface CatalogView {
  schema: "stellar-forge.sf88.collection-catalog.v1";
  path: string;
  sha256: string;
  bytes: number;
  source: string | null;
  rows: CatalogRow[];
}
export interface EditionInput {
  planId: string;
  planSha256: string;
  collectionId: string;
  name: string;
  values?: Record<string, string>;
}
export interface AcceptedRequestTerms {
  scheme: "exact";
  network: "stellar:testnet" | "stellar:pubnet";
  asset: string;
  payTo: string;
  maxAtomic: string;
  maxTimeoutSeconds?: number;
  paymentFlow?: "authorization" | "upfront";
}
export interface NativeOperation {
  intentId: string;
  url: string;
  method: string;
  expect: AcceptedRequestTerms;
  bodyFile?: string;
  bodyBytes?: number;
  bodySha256?: string;
  headers?: Record<string, string>;
  ticketFile?: string;
  ticketHeader?: string;
  [key: string]: unknown;
}
export interface NativeCollectionPreview {
  schema: "stellar-forge.sf88.collection-preview.v1";
  itemCount: number;
  previewSha256: string;
  items: Array<{
    index: number;
    intentId: string;
    sourceConfig: { path: string; sha256: string; bytes: number };
    operation: NativeOperation;
    responseDestination: string | null;
    body: { sha256: string; bytes: number } | null;
    ticket: Record<string, unknown> | null;
    dependencies: Record<string, unknown>;
  }>;
  totals: Array<{
    network: string;
    asset: string;
    payTo: string;
    scheme: string;
    paymentFlow: string;
    maxAtomic: string;
    itemCount: number;
  }>;
}
export interface PreparedRequest {
  key: string;
  name: string;
  intentId: string;
  configFile: string;
  discovery: {
    path: string;
    sha256: string;
    bytes: number;
    retainedPath: string;
    rowIndex: number;
    acceptIndex: number;
  };
  operator: {
    configFile: string;
    sha256: string;
    actor: string;
    service: string;
    policy: string;
    ledger: string;
    signerModule: string;
    evidenceDir: string;
    workspaceDirectory?: string;
    manifestSha256?: string;
  };
  responseOut: string | null;
  operation: NativeOperation;
  operationTicket: Record<string, unknown> | null;
}
export interface OriginalCollection {
  id: string;
  name: string;
  state: string;
  manifestSha256: string;
  previewSha256: string;
  items: Array<Record<string, unknown> & { intentId: string; state: string }>;
  [key: string]: unknown;
}
export type EditionPhase = "PREPARING" | "PREPARED" | "REVIEW_REQUIRED" | "CREATED";
export interface EditionView {
  schema: "stellar-forge.sf88.collection-edition.v1";
  collectionId: string;
  name: string;
  planId: string;
  planSha256: string;
  values: Record<string, string>;
  createdAt: string;
  editionSha256: string | null;
  phase: EditionPhase;
  preview: NativeCollectionPreview | null;
  requests: PreparedRequest[];
  workspaceByIntent: Record<string, string>;
  collection: OriginalCollection | null;
  issues: Array<{ code: string; key?: string }>;
}
export interface EditionSummary {
  collectionId: string;
  name: string;
  planId?: string;
  planSha256?: string;
  values?: Record<string, string>;
  createdAt?: string;
  editionSha256?: string | null;
  phase: EditionPhase;
  requestCount?: number;
  error?: string;
}
export interface RequestOptions { signal?: AbortSignal }
export interface CreateEditionInput {
  collectionId: string;
  expectedEditionSha256: string;
  expectedPreviewSha256: string;
}
export interface CollectionComposerClient {
  readonly origin: string;
  listPlans(options?: RequestOptions): Promise<{
    schema: "stellar-forge.sf88.collection-plans.v1";
    directory: string;
    plans: PlanSummary[];
  }>;
  inspectPlan(input: { id: string; planSha256: string }, options?: RequestOptions): Promise<SavedPlan>;
  savePlan(input: { plan: CollectionPlan }, options?: RequestOptions): Promise<SavedPlan>;
  inspectCatalog(input: { path: string }, options?: RequestOptions): Promise<CatalogView>;
  listEditions(options?: RequestOptions): Promise<{
    schema: "stellar-forge.sf88.collection-editions.v1";
    directory: string;
    editions: EditionSummary[];
  }>;
  inspectEdition(input: { collectionId: string }, options?: RequestOptions): Promise<EditionView>;
  prepareEdition(input: EditionInput, options?: RequestOptions): Promise<EditionView>;
  createEdition(input: CreateEditionInput, options?: RequestOptions): Promise<EditionView>;
}
export declare function createCollectionComposerClient(options: {
  url: string;
  fetch?: typeof globalThis.fetch;
}): CollectionComposerClient;

// MIT — Typed-method HTTP client for the original private Collections listener.
const need = (ok, code) => { if (!ok) throw Object.assign(new Error(code), { code }); };
const plain = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const id = value => {
  need(typeof value === 'string' && /^[A-Za-z0-9][A-Za-z0-9._-]{0,79}$/.test(value), 'COLLECTION_PLAN_ID_INVALID');
  return encodeURIComponent(value);
};
const revision = value => {
  need(typeof value === 'string' && /^[a-f0-9]{64}$/.test(value), 'COLLECTION_PLAN_REVISION_REQUIRED');
  return value;
};
/**
 * Open the existing listener from its private URL. The client creates no host.
 * Caller-selected fetch allows the original trusted host transport to be reused.
 */
export function createCollectionComposerClient({ url, fetch: send = globalThis.fetch } = {}) {
  let parsed;
  try { parsed = new URL(url); } catch {}
  need(parsed && !parsed.username && !parsed.password && !parsed.search
    && parsed.pathname === '/' && typeof send === 'function'
    && (parsed.protocol === 'https:' || parsed.protocol === 'http:'
      && ['127.0.0.1', '[::1]', 'localhost'].includes(parsed.hostname)),
  'COLLECTION_AUTHORING_CONNECTION_INVALID');
  const token = parsed.hash.slice(1);
  need(/^[a-f0-9]{64}$/.test(token), 'COLLECTION_AUTHORING_SESSION_REQUIRED');
  const origin = parsed.origin;
  async function request(path, input, { signal } = {}) {
    const response = await send(origin + path, {
      method: input === undefined ? 'GET' : 'POST',
      headers: { Authorization: 'Bearer ' + token,
        ...(input === undefined ? {} : { 'Content-Type': 'application/json' }) },
      ...(input === undefined ? {} : { body: JSON.stringify(input) }),
      cache: 'no-store', credentials: 'omit', redirect: 'error', signal,
    });
    need(response && typeof response.json === 'function', 'COLLECTION_AUTHORING_RESPONSE_INVALID');
    let payload;
    try { payload = await response.json(); } catch {
      throw Object.assign(new Error('COLLECTION_AUTHORING_RESPONSE_INVALID'),
        { code: 'COLLECTION_AUTHORING_RESPONSE_INVALID', status: response.status });
    }
    if (!response.ok) {
      const code = /^[A-Z0-9_]{1,120}$/.test(payload?.error ?? '') ? payload.error : 'COLLECTION_AUTHORING_REQUEST_FAILED';
      throw Object.assign(new Error(code), { code, status: response.status });
    }
    need(plain(payload), 'COLLECTION_AUTHORING_RESPONSE_INVALID');
    return payload;
  }
  return Object.freeze({
    origin,
    listPlans: options => request('/api/composer/plans', undefined, options),
    inspectPlan: ({ id: planId, planSha256 }, options) =>
      request('/api/composer/plans/' + id(planId) + '/' + revision(planSha256), undefined, options),
    savePlan: ({ plan }, options) => request('/api/composer/plans', { plan }, options),
    inspectCatalog: ({ path }, options) => request('/api/composer/catalog', { path }, options),
    listEditions: options => request('/api/composer/editions', undefined, options),
    inspectEdition: ({ collectionId }, options) => request('/api/composer/editions/' + id(collectionId), undefined, options),
    prepareEdition: (input, options) => request('/api/composer/editions/prepare', input, options),
    createEdition: ({ collectionId, expectedEditionSha256, expectedPreviewSha256 }, options) =>
      request('/api/composer/editions/' + id(collectionId) + '/create',
        { expectedEditionSha256: revision(expectedEditionSha256), expectedPreviewSha256: revision(expectedPreviewSha256) }, options),
  });
}

// MIT — Retained authoring over the original SF88 builder and collection controller.
import { createHash } from 'node:crypto';
import { readdir, lstat, realpath } from 'node:fs/promises';
import { join, resolve, dirname, isAbsolute } from 'node:path';
import { isDeepStrictEqual as same } from 'node:util';
import { prepareReview } from '../prepare.mjs';
import { config, execution, bytes as originalBytes } from '../config.mjs';
import { openWorkspace } from '../workspace.mjs';
import { readRequestBody, requestBodyPin } from '../request-body.mjs';
import { loadOperationTicket, operationTicketView } from '../operation-ticket.mjs';
import { previewCollection, acquireCollectionLease } from '../collections/model.mjs';
import { initializationDirectory, initializationBytes, optionalInitializationBytes,
  retainInitializationFile, retainInitializationRecord } from '../initialization.mjs';
import { COLLECTION_PLAN_SCHEMA, COLLECTION_EDITION_SCHEMA, validateCollectionPlan,
  resolveCollectionEdition, stableJson, plain, fields, need } from './plan.mjs';

const HASH = /^[a-f0-9]{64}$/;
const ID = /^[A-Za-z0-9][A-Za-z0-9._-]{0,79}$/;
const KEY = /^[A-Za-z0-9][A-Za-z0-9._-]{0,39}$/;
const MAX_INPUT = 128 * 1024 * 1024;
const MAX_RECORD = 32 * 1024 * 1024;
const hash = bytes => createHash('sha256').update(bytes).digest('hex');
const json = value => Buffer.from(stableJson(value) + '\n');
const parse = bytes => {
  try { return JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes)); }
  catch { need(false, 'COLLECTION_AUTHORING_JSON_INVALID'); }
};
const codeOf = error => /^[A-Z0-9_]{1,120}$/.test(error?.code ?? '')
  ? error.code : 'COLLECTION_AUTHORING_SOURCE_UNAVAILABLE';
function absolute(path) {
  need(typeof path === 'string' && isAbsolute(path) && resolve(path) === path
    && path !== '/' && !path.includes('\0'), 'COLLECTION_AUTHORING_ABSOLUTE_PATH_REQUIRED');
  return path;
}
function checkedId(id) { need(ID.test(id ?? ''), 'COLLECTION_PLAN_ID_INVALID'); return id; }
function checkedHash(value) { need(HASH.test(value ?? ''), 'COLLECTION_PLAN_REVISION_REQUIRED'); return value; }
async function readOriginal(path, limit) {
  absolute(path);
  need(await realpath(path) === path, 'COLLECTION_AUTHORING_SOURCE_PATH_AMBIGUOUS');
  return initializationBytes(path, limit);
}
// Public saved catalogs use the original regular-file reader; snapshots stay private.
async function readDiscovery(path) {
  absolute(path);
  need(await realpath(path) === path, 'COLLECTION_AUTHORING_SOURCE_PATH_AMBIGUOUS');
  return originalBytes(path, 1048576, 'INVALID_DISCOVERY_FILE');
}
async function optionalRecord(path, limit = MAX_RECORD) {
  const bytes = await optionalInitializationBytes(path, limit);
  return bytes === null ? null : parse(bytes);
}
async function directories(path) {
  const entries = await readdir(path, { withFileTypes: true }).catch(error => {
    if (error.code === 'ENOENT') return []; throw error;
  });
  return entries.filter(item => item.isDirectory() && !item.isSymbolicLink()).map(item => item.name);
}
function filePath(path, key) {
  need(typeof path === 'string' && (
    /^catalogs\/[a-f0-9]{64}\.json$/.test(path)
    || new RegExp('^inputs/' + key.replaceAll('.', '\\.') +
      '/(?:operator-source\\.json|operator-workspace\\.json|request-body\\.bin|operation-ticket\\.json|config\\.json)$').test(path)),
  'COLLECTION_EDITION_FILE_INVALID');
  return path;
}
function checkedCapture(value, key, base) {
  need(value?.schema === 'stellar-forge.sf88.collection-request-capture.v1'
    && value.request?.key === key && KEY.test(key)
    && typeof value.request.intentId === 'string'
    && value.request.configFile === join(base, 'inputs', key, 'config.json')
    && Array.isArray(value.files) && value.files.length >= 3 && value.files.length <= 6,
  'COLLECTION_EDITION_CAPTURE_INVALID');
  const paths = new Set();
  for (const file of value.files) {
    filePath(file.path, key);
    need(!paths.has(file.path) && HASH.test(file.sha256 ?? '') && Number.isSafeInteger(file.bytes)
      && file.bytes >= 0 && file.bytes <= MAX_INPUT, 'COLLECTION_EDITION_FILE_INVALID');
    paths.add(file.path);
  }
  for (const name of ['operator-source.json', 'config.json'])
    need(paths.has('inputs/' + key + '/' + name), 'COLLECTION_EDITION_CAPTURE_INVALID');
  need(paths.has('catalogs/' + value.request.discovery?.sha256 + '.json'),
    'COLLECTION_EDITION_CAPTURE_INVALID');
  return value;
}
async function verifyFiles(base, files) {
  let total = 0;
  for (const file of files) {
    total += file.bytes; need(total <= MAX_INPUT, 'COLLECTION_AUTHORING_INPUT_BYTES_EXCEEDED');
    const path = join(base, file.path);
    await initializationDirectory(dirname(path));
    const raw = await initializationBytes(path, Math.max(file.bytes, 1));
    need(raw.length === file.bytes && hash(raw) === file.sha256, 'COLLECTION_EDITION_INPUT_CHANGED');
  }
}
function uniqueFiles(captures) {
  const files = new Map();
  for (const capture of captures) for (const file of capture.files) {
    need(!files.has(file.path) || same(files.get(file.path), file), 'COLLECTION_EDITION_INPUT_CHANGED');
    files.set(file.path, file);
  }
  const result = [...files.values()].sort((a, b) => a.path.localeCompare(b.path));
  need(result.reduce((sum, file) => sum + file.bytes, 0) <= MAX_INPUT,
    'COLLECTION_AUTHORING_INPUT_BYTES_EXCEEDED');
  return result;
}
function boundOperator(original, prepared, manifest) {
  const prior = execution(original), chosen = execution(prepared);
  const limit = manifest?.signer?.maxAtomic ?? prior.op.expect.maxAtomic;
  for (const key of ['scheme', 'network', 'asset', 'payTo'])
    need(prior.op.expect[key] === chosen.op.expect[key], 'COLLECTION_PLAN_OPERATOR_TERMS_MISMATCH');
  need((prior.op.expect.paymentFlow ?? 'authorization') === (chosen.op.expect.paymentFlow ?? 'authorization')
    && typeof limit === 'string' && BigInt(chosen.op.expect.maxAtomic) <= BigInt(limit),
  'COLLECTION_PLAN_OPERATOR_LIMIT_EXCEEDED');
  return chosen;
}
async function readOperator(request) {
  let original, path, manifest = null, manifestBytes = null;
  if (request.operatorWorkspace !== undefined) {
    const directory = absolute(request.operatorWorkspace);
    await initializationDirectory(directory);
    const opened = await openWorkspace(['--dir', directory]);
    path = opened.configPath; original = opened.config; manifest = opened.manifest;
    manifestBytes = await readOriginal(join(directory, 'workspace.json'), 65536);
    need(same(parse(manifestBytes), manifest), 'COLLECTION_PLAN_OPERATOR_CHANGED');
  } else {
    path = absolute(request.operatorConfigFile);
    original = await config(path);
  }
  const raw = await readOriginal(path, 65536);
  need(same(parse(raw), original) && raw.equals(await readOriginal(path, 65536)),
    'COLLECTION_PLAN_OPERATOR_CHANGED');
  execution(original);
  return { original, path, raw, manifest, manifestBytes };
}
async function checkOperatorBinding(request) {
  const binding = request.operator;
  const current = await readOperator(binding.workspaceDirectory
    ? { operatorWorkspace: binding.workspaceDirectory } : { operatorConfigFile: binding.configFile });
  need(current.path === binding.configFile && hash(current.raw) === binding.sha256
    && (binding.manifestSha256 === undefined || hash(current.manifestBytes) === binding.manifestSha256),
  'COLLECTION_PLAN_OPERATOR_CHANGED');
}
/** Read the exact saved native catalog. Selection validation belongs to prepareReview. */
export async function inspectCollectionCatalog({ path } = {}) {
  const raw = await readDiscovery(path), saved = parse(raw);
  need(plain(saved), 'INVALID_SAVED_DISCOVERY');
  let rows, source = null;
  if (saved.schema === 'scf61-observed-native-page-v1') {
    need(saved.readOnly === true && saved.paidOrSettled === false
      && !['resources', 'items', 'originalListings'].some(key => Object.hasOwn(saved, key))
      && (saved.sourceUrl === undefined || typeof saved.sourceUrl === 'string'), 'INVALID_SAVED_DISCOVERY');
    rows = saved.nativeProviderRows; source = saved.sourceUrl ?? null;
  } else if (saved.mode === 'ORIGINAL_UNSIGNED_CATALOG') {
    need(!Object.hasOwn(saved, 'resources') && !Object.hasOwn(saved, 'items')
      && ['resources', 'items'].includes(saved.sourceEnvelope) && typeof saved.source === 'string',
    'INVALID_SAVED_DISCOVERY');
    rows = saved.originalListings; source = saved.source;
  } else {
    const resources = Object.hasOwn(saved, 'resources'), items = Object.hasOwn(saved, 'items');
    need(resources !== items && !Object.hasOwn(saved, 'originalListings'), 'INVALID_SAVED_DISCOVERY');
    rows = saved[resources ? 'resources' : 'items'];
  }
  need(Array.isArray(rows), 'INVALID_SAVED_DISCOVERY');
  return { schema: 'stellar-forge.sf88.collection-catalog.v1', path, sha256: hash(raw), bytes: raw.length, source,
    rows: rows.map((row, index) => ({ index,
      resource: typeof row?.resource === 'string' ? row.resource : row?.resource?.url ?? '',
      description: row?.description ?? row?.resource?.description ?? '',
      method: row?.extensions?.bazaar?.info?.input?.method ?? 'GET',
      accepts: Array.isArray(row?.accepts) ? row.accepts.map((item, index) => ({ ...item, index })) : [],
